from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallMovingAverageAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .CallsOnly()
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.blocked_date = None

    def OnData(self, slice_data: Slice):
        today = self.Time.date()

        # Immediately liquidate any unexpected SPY equity position.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected exercise/assignment handling: liquidating "
                "SPY equity position of {}".format(spy_quantity)
            )
            self.MarketOrder(
                self.spy,
                -spy_quantity,
                "Unexpected exercise or assignment"
            )
            self.blocked_date = today

        # Expiration handling takes precedence over normal exits and entries.
        if self.held_symbol is not None and self.expiration_date is not None:
            if today >= self.expiration_date:
                self.blocked_date = today
                self._submit_exit("Expiration protection")
            elif self._is_expiration_eve(today):
                if self.Time.hour == 15 and self.Time.minute >= 45:
                    self._submit_exit("Expiration-eve time stop")

        # Profit target is evaluated on each minute Slice.
        if (
            self.held_symbol is not None
            and self.expiration_date is not None
            and today < self.expiration_date
            and self.exit_ticket is None
        ):
            midpoint = self._current_option_midpoint(slice_data)
            if (
                midpoint is not None
                and self.entry_price is not None
                and midpoint >= 1.50 * self.entry_price
            ):
                self._submit_exit("50% profit target")

        # Build a five-minute bar only from five contiguous actual minute bars.
        if self.spy in slice_data.Bars:
            self._process_minute_bar(slice_data.Bars[self.spy], slice_data)

    def _process_minute_bar(self, minute_bar, slice_data):
        bar_time = minute_bar.Time.replace(second=0, microsecond=0)

        if not (9 <= bar_time.hour < 16):
            self._reset_bucket()
            return

        if bar_time.hour == 9 and bar_time.minute < 30:
            self._reset_bucket()
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(minute=bucket_minute)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = []

        expected_time = bucket_start + timedelta(minutes=len(self.bucket_bars))
        if bar_time != expected_time:
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) != 5:
            return

        consolidated_close = self.bucket_bars[-1].Close
        consolidated_end = bucket_start + timedelta(minutes=5)

        self._reset_bucket()
        self._process_five_minute_close(
            consolidated_end,
            consolidated_close,
            slice_data
        )

    def _process_five_minute_close(self, bar_end, close, slice_data):
        if len(self.fast_values) == 5 and len(self.slow_values) == 20:
            previous_fast = sum(self.fast_values) / 5.0
            previous_slow = sum(self.slow_values) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.fast_values.append(close)
        self.slow_values.append(close)

        if previous_fast is None or len(self.slow_values) < 20:
            return

        current_fast = sum(self.fast_values) / 5.0
        current_slow = sum(self.slow_values) / 20.0

        crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible_time = (
            datetime.min.replace(hour=9, minute=45).time()
            <= bar_time
            <= datetime.min.replace(hour=14, minute=30).time()
        )

        if crossover and eligible_time:
            self._try_enter(slice_data)

    def _try_enter(self, slice_data):
        today = self.Time.date()

        if today == self.blocked_date:
            return

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None:
            return

        if self._has_option_holding():
            return

        if self.option_symbol not in slice_data.OptionChains:
            self.Debug("Skipped selection: no option chain in current Slice")
            return

        chain = slice_data.OptionChains[self.option_symbol]
        contracts = list(chain.Contracts.Values)

        minimum_expiration = today + timedelta(days=7)
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not eligible_expirations:
            self.Debug("Skipped selection: no expiration at least 7 days out")
            return

        selected_expiration = eligible_expirations[0]

        calls = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
            )
        ]

        if not calls:
            self.Debug(
                "Skipped selection: no call contracts at selected expiration"
            )
            return

        if self.spy not in slice_data.Bars:
            self.Debug("Skipped selection: no current SPY price")
            return

        underlying_price = slice_data.Bars[self.spy].Close
        if underlying_price <= 0:
            self.Debug("Skipped selection: invalid current SPY price")
            return

        # Strike rule: nearest at-the-money call, with deterministic tie-breaks.
        selected_contract = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected_contract.Symbol,
            1,
            "Bullish five-minute crossover entry"
        )

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            reason
        )

    def _current_option_midpoint(self, slice_data):
        if self.held_symbol is None:
            return None

        bid = None
        ask = None

        if self.held_symbol in slice_data.QuoteBars:
            quote = slice_data.QuoteBars[self.held_symbol]
            if quote.Bid is not None:
                bid = quote.Bid.Close
            if quote.Ask is not None:
                ask = quote.Ask.Close

        if (
            (bid is None or ask is None)
            and self.option_symbol in slice_data.OptionChains
        ):
            chain = slice_data.OptionChains[self.option_symbol]
            if self.held_symbol in chain.Contracts:
                contract = chain.Contracts[self.held_symbol]
                bid = contract.BidPrice
                ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return None

        return (bid + ask) / 2.0

    def _has_option_holding(self):
        for security in self.Portfolio.Values:
            if (
                security.Type == SecurityType.Option
                and security.Quantity > 0
            ):
                return True
        return False

    def _is_expiration_eve(self, current_date):
        if self.expiration_date is None or current_date >= self.expiration_date:
            return False

        candidate = current_date + timedelta(days=1)
        while candidate < self.expiration_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return False
            candidate += timedelta(days=1)

        return True

    def _reset_bucket(self):
        self.bucket_start = None
        self.bucket_bars = []

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.expiration_date = (
                self.Securities[self.held_symbol].Symbol.ID.Date.date()
            )

            self.Debug(
                "Entry filled: {} {} @ {:.4f}".format(
                    self.held_symbol.Value,
                    order_event.FillQuantity,
                    self.entry_price
                )
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} @ {:.4f}".format(
                    order_event.Symbol.Value,
                    order_event.FillPrice
                )
            )
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.expiration_date = None

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.Debug("Entry order did not fill: {}".format(
                order_event.Status
            ))
            self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.exit_ticket = None
