from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.held_option = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

        self.current_bucket_end = None
        self.bucket_count = 0
        self.bucket_open = None
        self.bucket_high = None
        self.bucket_low = None
        self.bucket_close = None
        self.last_minute_end = None

    def OnData(self, slice: Slice):
        # Handle unexpected SPY equity positions, such as exercise or assignment.
        spy_quantity = self.Portfolio[self.spy_symbol].Quantity
        if spy_quantity != 0:
            if self.equity_liquidation_ticket is None or not self._is_open(
                self.equity_liquidation_ticket
            ):
                self.Debug(
                    f"Unexpected SPY equity position detected: {spy_quantity}; "
                    "liquidating immediately."
                )
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy_symbol, -spy_quantity
                )

        # Manage the held option on every minute Slice.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            # Never intentionally carry the contract into expiration.
            if self.Time.date() >= expiry_date:
                self.expiration_block_date = self.Time.date()
                self._submit_exit("expiration processing")
            else:
                # Time stop on the immediately preceding trading day at 15:45.
                previous_trading_day = self._previous_trading_day(expiry_date)
                if (
                    self.Time.date() == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute == 45
                ):
                    self._submit_exit("pre-expiration time stop")
                else:
                    self._check_profit_target(slice)

        # Build a five-minute bar only from actual minute bars.
        spy_bar = None
        try:
            spy_bar = slice.Bars[self.spy_symbol]
        except Exception:
            pass

        if spy_bar is not None:
            self._consume_minute_bar(spy_bar, slice)

    def _consume_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        if end.tzinfo is not None:
            end = end.replace(tzinfo=None)

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        minute_end = end.replace(second=0, microsecond=0)
        minute_start = minute_end - timedelta(minutes=1)

        bucket_start_minute = 30 + ((minute_end.minute - 31) // 5) * 5
        bucket_start = minute_end.replace(
            minute= bucket_start_minute,
            second=0,
            microsecond=0
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        # A gap or bucket transition invalidates an incomplete five-minute bar.
        if (
            self.current_bucket_end != bucket_end
            or (
                self.last_minute_end is not None
                and minute_start != self.last_minute_end
            )
        ):
            if (
                self.current_bucket_end is not None
                and self.bucket_count == 5
                and self.last_minute_end == self.current_bucket_end
            ):
                self._on_five_minute_bar(
                    self.bucket_close,
                    self.current_bucket_end,
                    slice
                )

            self.current_bucket_end = bucket_end
            self.bucket_count = 0
            self.bucket_open = None
            self.bucket_high = None
            self.bucket_low = None
            self.bucket_close = None

        if self.bucket_count == 0:
            self.bucket_open = bar.Open
            self.bucket_high = bar.High
            self.bucket_low = bar.Low
        else:
            self.bucket_high = max(self.bucket_high, bar.High)
            self.bucket_low = min(self.bucket_low, bar.Low)

        self.bucket_close = bar.Close
