        fast = None
        slow = None

        self.fast_values.append(close)
        if len(self.fast_values) >= 5:
            fast = sum(self.fast_values[-5:]) / 5.0

        self.slow_values.append(close)
        if len(self.slow_values) >= 20:
            slow = sum(self.slow_values[-20:]) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and fast is not None
            and slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        if (
            bullish_cross
            and eligible_time
            and self.held_option is None
            and not self._entry_order_open()
            and self.expiration_block_date != self.Time.date()
        ):
            self._select_and_enter(slice, close)

    def _select_and_enter(self, slice: Slice, underlying_price):
        chain = None

        try:
            chain = slice.OptionChains[self.option_symbol]
        except Exception:
            try:
                for candidate in slice.OptionChains.Values:
                    if candidate.Symbol == self.option_symbol:
                        chain = candidate
                        break
            except Exception:
                chain = None

