        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not calls:
            self.Debug("Skipped entry: selected expiration has no valid call contracts.")
            return

        # Select the nearest-to-the-money call at the selected expiration.
        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - float(underlying_price)),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={selected_expiry} strike={selected.Strike}"
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        quote = None
        try:
            quote = slice.QuoteBars[self.held_option.Symbol]
        except Exception:
            return

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel(f"Replacing exit: {reason}")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity
        )
        self.Debug(f"Exit submitted: {reason} {self.held_option.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Submitted,
            ):
                if order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            )
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )
                self.held_option = None
                self.entry_price = None
            self.exit_ticket = None

        if (
            order_event.Symbol == self.spy_symbol
            and order_event.Status == OrderStatus.Filled
            and order_event.FillQuantity != 0
        ):
            self.Debug(
                f"Unexpected SPY equity fill detected: "
                f"{order_event.FillQuantity}; liquidating."
            )

    def _entry_order_open(self):
        return self.entry_ticket is not None and self._is_open(self.entry_ticket)

    @staticmethod
    def _is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate
