        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedEquityPosition()

        if self.expiration_processing_done:
            return

        self.UpdateFiveMinuteBar(slice)

        if self.held_contract is not None:
            self.EvaluateOpenPosition(slice)

    def UpdateFiveMinuteBar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        now = self.Time

        if now.hour < 9 or (now.hour == 9 and now.minute < 31):
            return
        if now.hour > 16 or (now.hour == 16 and now.minute > 0):
            return

        minute_key = now.replace(second=0, microsecond=0)
        end_minute = ((now.minute + 4) // 5) * 5

        if end_minute >= 60:
            bucket_end = (now + timedelta(hours=1)).replace(
                minute=0, second=0, microsecond=0
            )
        else:
            bucket_end = now.replace(
                minute=end_minute, second=0, microsecond=0
            )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.FinalizeFiveMinuteBar()

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_minutes = {}

        self.bucket_minutes[minute_key] = float(bar.Close)

        if minute_key == bucket_end.replace(second=0, microsecond=0):
            self.FinalizeFiveMinuteBar()

    def FinalizeFiveMinuteBar(self):
        if self.bucket_end is None:
            return

        end = self.bucket_end
        expected = [
            end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self.bucket_minutes for t in expected):
            self.bucket_end = None
            self.bucket_minutes = {}
            return

        close = self.bucket_minutes[end - timedelta(minutes=0)]

        old_fast = float(self.fast.Current.Value) if self.fast.IsReady else None
        old_slow = float(self.slow.Current.Value) if self.slow.IsReady else None

        self.fast.Update(end, close)
        self.slow.Update(end, close)

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and old_fast <= old_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.bucket_end = None
        self.bucket_minutes = {}

        if not bullish_cross:
            return

        if not (9 <= end.hour <= 14):
            return
        if end.hour == 9 and end.minute < 45:
            return
        if end.hour == 14 and end.minute > 30:
            return

        if self.held_contract is not None or self.IsEntryOrderOpen():
            return

        self.TryEnterFromCurrentSlice()

    def TryEnterFromCurrentSlice(self):
        # Entry selection is performed from the current Slice only.
        # This method is called by FinalizeFiveMinuteBar, so the latest
        # option chain is retained from OnData.
        slice = self.current_slice
        if slice is None or self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no current option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        expiry = expiries[0]
        calls = [
            contract for contract in chain
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call contract at selected expiry.")
            return

        underlying_price = float(self.Securities[self.spy].Price)
        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId

    def EvaluateOpenPosition(self, slice: Slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        expiry = self.held_contract.ID.Date.date()
        today = self.Time.date()

        if self.IsPreviousTradingDay(today, expiry):
            if self.Time.hour > 15 or (
                self.Time.hour == 15 and self.Time.minute >= 45
            ):
                self.SubmitExit("time stop")
                return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        if self.held_contract not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
