from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpySevenDayCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.current_bucket_end = None
        self.current_bucket_close = None
        self.current_bucket_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(current_date)
        self._evaluate_profit_target(slice)
        self._evaluate_time_stop(now)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._update_five_minute_bar(bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime
        current_date = end_time.date()

        if end_time.time() < time(9, 30) or end_time.time() > time(16, 0):
            return

        bucket_end = self._bucket_end(end_time)

        if self.current_bucket_date != current_date:
            self.current_bucket_date = current_date
            self.current_bucket_end = bucket_end
            self.current_bucket_close = minute_bar.Close
            return

        if bucket_end != self.current_bucket_end:
            if self.current_bucket_close is not None:
                self._process_completed_bar(
                    self.current_bucket_end,
                    self.current_bucket_close,
                    slice
                )

            self.current_bucket_end = bucket_end
            self.current_bucket_close = minute_bar.Close
        else:
            self.current_bucket_close = minute_bar.Close

        # Complete the bar immediately when its final minute arrives.
        if end_time.time().minute % 5 == 0:
            self._process_completed_bar(
                self.current_bucket_end,
                self.current_bucket_close,
                slice
            )
            self.current_bucket_end = None
            self.current_bucket_close = None

    def _bucket_end(self, end_time: datetime) -> datetime:
        minute = end_time.minute
        minutes_to_add = 5 - (minute % 5)
        if minutes_to_add == 0:
            minutes_to_add = 5

        bucket = end_time.replace(
            second=0,
            microsecond=0
        )
        return bucket + timedelta(minutes=minutes_to_add)

    def _process_completed_bar(
        self,
        bar_end: datetime,
        close: float,
        slice: Slice
    ):
        bar_time = bar_end.time()

        if not (time(9, 30) <= bar_time <= time(16, 0)):
            return

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(
                list(self.closes)[-self.fast_period:]
            ) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(
            list(self.closes)[-self.fast_period:]
        ) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        if self.expiration_block_date == self.Time.date():
            return

        chain = None

        if self.option.Symbol in slice.OptionChains:
            chain = slice.OptionChains[self.option.Symbol]
        else:
            for candidate in slice.OptionChains.Values:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        underlying_price = float(self.Securities[self.spy].Price)

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no call contract for {selected_expiry}."
            )
            return

        # Select the call whose strike is nearest to the current SPY price.
        selected = min(
            candidates,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self, now: datetime):
        if self.held_symbol is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if now.date() >= expiry_date:
            return

        next_trading_day = now.date() + timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            next_trading_day
        ):
            next_trading_day += timedelta(days=1)

        if (
            next_trading_day == expiry_date
            and now.time() >= time(15, 45)
        ):
            self._submit_exit("expiration-eve time stop")

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date

            if self.Portfolio[self.held_symbol].Invested:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested before entry completed.")
            self.entry_ticket = None

        if self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason}).")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Invested:
            self.Debug(
                f"Unexpected SPY equity position detected "
                f"({holding.Quantity}); liquidating immediately."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None

                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price:.4f}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exit filled: {order_event.Symbol}, "
                    f"price={float(order_event.FillPrice):.4f}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error
        ):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.Debug(
                    f"Entry order did not fill: {order_event.Status}."
                )
                self.entry_ticket = None

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exit order did not fill: {order_event.Status}."
                )
                self.exit_ticket = None

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
