                f"Skipped entry: no call contract for {selected_expiry}."
            )
            return

        # Select the call whose strike is nearest to the current SPY price.
        selected = min(
            candidates,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
