        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice: Slice):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.IsOpen(self.entry_ticket):
            return

        chains = slice.OptionChains
        chain = chains.get(self.spy_option.Symbol)

        if chain is None:
