            self.expiration_block_date = self.Time.date()

    def CancelEntryOrder(self):
        if self.IsOpen(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")
            self.entry_ticket = None

    def CancelExitOrder(self):
        if self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

    def GetExpirationDate(self, symbol):
        expiration = symbol.ID.Date
        return expiration.date() if isinstance(expiration, datetime) else expiration

    def IsTradingDayImmediatelyBefore(self, current_date, expiration_date):
        candidate = current_date + timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate += timedelta(days=1)

        return candidate == expiration_date
