from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.bucket_end = None
        self.bucket_times = []
        self.bucket_closes = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        # Immediately remove any unexpected SPY equity position.
        spy_quantity = self.Portfolio[self.spy_symbol].Quantity
        if spy_quantity != 0 and self.equity_liquidation_ticket is None:
            self.Debug(
                f"Unexpected SPY equity position detected: {spy_quantity}; "
                "liquidating immediately."
            )
            self.no_entry_date = today
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy_symbol, -spy_quantity
            )

        # Handle an existing option position.
        if self.entry_symbol is not None:
            self._process_existing_position(slice)

        # Build a five-minute bar from actual minute bars only.
        if self.spy_symbol in slice.Bars:
            completed_close = self._update_five_minute_bar(
                slice.Bars[self.spy_symbol]
            )

            if completed_close is not None:
                self._evaluate_entry(slice, completed_close)

    def _update_five_minute_bar(self, minute_bar):
        t = self.Time.replace(second=0, microsecond=0)

        # Regular-session minute bars only.
        if t.time() < self._time(9, 31) or t.time() > self._time(16, 0):
            return None

        remainder = t.minute % 5
        minutes_to_end = (5 - remainder) % 5
        bucket_end = t + timedelta(minutes=minutes_to_end)

        bucket_start = bucket_end - timedelta(minutes=4)

        # A valid five-minute bar must begin at its exact expected minute.
        if t == bucket_start:
            self.bucket_end = bucket_end
            self.bucket_times = [t]
            self.bucket_closes = [float(minute_bar.Close)]
            return None

        if self.bucket_end != bucket_end:
            self.bucket_end = None
            self.bucket_times = []
            self.bucket_closes = []
            return None

        expected_time = self.bucket_times[-1] + timedelta(minutes=1)
        if t != expected_time:
            # Missing minute: discard the incomplete interval.
            self.bucket_end = None
            self.bucket_times = []
            self.bucket_closes = []
            return None

        self.bucket_times.append(t)
        self.bucket_closes.append(float(minute_bar.Close))

        if len(self.bucket_closes) != 5:
            return None

        close = self.bucket_closes[-1]

        self.bucket_end = None
        self.bucket_times = []
        self.bucket_closes = []

        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return None

        fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        # RollingWindow[0] is current. The previous signal values are
        # calculated by removing the current close from each window.
        previous_fast = (
            sum(self.fast_window[i] for i in range(1, 5)) + self.fast_window[4]
        ) / 5.0
        previous_slow = sum(self.slow_window[i] for i in range(1, 20)) / 20.0

        bullish_cross = previous_fast <= previous_slow and fast > slow

        if bullish_cross:
            return (self.Time, close)

        return None

    def _evaluate_entry(self, slice, completed_bar):
        bar_end, underlying_price = completed_bar

        if not (self._time(9, 45) <= bar_end.time() <= self._time(14, 30)):
            return

        if self.no_entry_date == bar_end.date():
            return

        if self.entry_symbol is not None:
            return

        if self._entry_order_open():
            return

        chain = self._get_current_chain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = bar_end.date() + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug(
                "Skipped entry: no call contract satisfies the expiration "
                "and strike rules."
            )
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in contracts
        )

        expiry_contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not expiry_contracts:
            self.Debug("Skipped entry: selected expiration has no valid calls.")
            return

        # Select the closest-to-ATM call; ties are resolved toward the lower
        # strike to make selection deterministic.
        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            f"Submitted entry: {self.entry_symbol} at "
            f"{bar_end.strftime('%Y-%m-%d %H:%M')}"
        )

    def _process_existing_position(self, slice):
        now = self.Time
        holding = self.Portfolio[self.entry_symbol]

        if holding.Quantity <= 0:
            return

        expiry = self.entry_symbol.ID.Date.date()

        # Never intentionally hold through expiration.
        if now.date() >= expiry:
            self.no_entry_date = now.date()
            self._submit_exit("expiration")
            return

        # Time stop on the trading day immediately preceding expiration.
        previous_trading_day = (
            self.Securities[self.spy_symbol]
            .Exchange
            .Hours
            .GetPreviousTradingDay(expiry)
        )

        if (
            now.date() == previous_trading_day.date()
            and now.time() >= self._time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        contract = self._find_held_contract(slice)
        if contract is None:
            return

