        end_time = bar.EndTime.time()
        eligible_time = (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_time
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross and eligible_time:
            self.pending_entry_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing(current_date)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(slice, current_date)

        self.EvaluateHeldOptionExit(slice, current_date)

    def TryEnter(self, slice, current_date):
        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()

                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call expiration.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in candidates)
        expiration_contracts = [
            contract
            for contract in candidates
            if contract.Expiry.date() == selected_expiry
        ]

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        # Strike rule: select the call nearest to the current SPY price.
        selected = min(
            expiration_contracts,
            key=lambda contract: (abs(contract.Strike - spot), contract.Strike)
        )

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_fill_quantity = 0
        self.exit_requested = False

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug(
            "Entry submitted: {} expiry={} strike={}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def EvaluateHeldOptionExit(self, slice, current_date):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiration_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if self.IsTradingDayImmediatelyBefore(current_date, expiration_date):
            if self.Time.time() >= datetime.strptime("15:45", "%H:%M").time():
                self.SubmitOptionExit("time stop")
                return

        contract = self.GetHeldContractFromSlice(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        if self.entry_price is not None:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self.SubmitOptionExit("50% profit target")

    def SubmitOptionExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_requested:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.CancelOpenExitOrders()

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_id = ticket.OrderId
        self.exit_requested = True

        self.Debug(
            "Exit submitted: {} quantity={} reason={}".format(
                self.held_option,
                quantity,
                reason
            )
        )

    def HandleExpirationProcessing(self, current_date):
        if self.held_option is None:
            return

        expiration_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if current_date >= expiration_date:
            self.no_entry_date = current_date
            self.SubmitOptionExit("expiration processing")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if self.spy_liquidation_order_id is None:
            ticket = self.MarketOrder(self.spy, -quantity)
            self.spy_liquidation_order_id = ticket.OrderId
            self.no_entry_date = self.Time.date()

            self.Debug(
                "Unexpected exercise/assignment handling: liquidating SPY quantity={}".format(
                    quantity
                )
            )

    def GetHeldContractFromSlice(self, slice):
        if self.held_option is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    return contract

        return None

    def CancelOpenExitOrders(self):
        if self.held_option is None:
            return

        open_orders = self.Transactions.GetOpenOrders(self.held_option)

        for order in open_orders:
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

    def IsTradingDayImmediatelyBefore(self, current_date, expiration_date):
        if current_date >= expiration_date:
            return False

        check_date = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while check_date >= current_date - timedelta(days=10):
            check_datetime = datetime(
                check_date.year,
                check_date.month,
                check_date.day
            )

            if exchange_hours.IsDateOpen(check_datetime):
                return current_date == check_date

            check_date -= timedelta(days=1)

        return False

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId
        status = order_event.Status

        if order_id == self.entry_order_id:
            if order_event.FillQuantity != 0:
                prior_quantity = self.entry_fill_quantity
                new_quantity = prior_quantity + order_event.FillQuantity

                if new_quantity != 0:
                    if self.entry_price is None:
                        self.entry_price = order_event.FillPrice
                    else:
                        self.entry_price = (
                            self.entry_price * prior_quantity
                            + order_event.FillPrice * order_event.FillQuantity
                        ) / new_quantity

                self.entry_fill_quantity = new_quantity

            if status == OrderStatus.Filled:
                self.Debug(
                    "Entry filled: symbol={} price={}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
                self.entry_order_id = None

            elif status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                if status != OrderStatus.None:
                    self.Debug("Entry order did not fill: {}".format(status))

                if self.entry_fill_quantity == 0:
                    self.entry_order_id = None
                    self.held_option = None
                    self.entry_price = None

        if order_id == self.exit_order_id:
            if status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: symbol={} price={}".format(
                        self.held_option,
                        order_event.FillPrice
                    )
                )

                self.exit_order_id = None
                self.exit_requested = False
                self.held_option = None
                self.entry_price = None
                self.entry_fill_quantity = 0

            elif status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None
                self.exit_requested = False

        if order_id == self.spy_liquidation_order_id:
            if status == OrderStatus.Filled:
                self.Debug("Unexpected SPY position liquidated.")
                self.spy_liquidation_order_id = None
            elif status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_liquidation_order_id = None

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option assignment/exercise event received.")
