from AlgorithmImports import *
from collections import defaultdict, deque
from datetime import datetime, timedelta, time as dtime


class SpyLongCallCrossover(QCAlgorithm):
    """
    SPY five-minute moving-average crossover strategy that buys one long call.

    Strike selection assumption:
    since no explicit strike rule was provided, the call whose strike is
    closest to the current raw SPY price is selected. Exact ties prefer the
    lower strike.
    """

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            False,
            1,
            False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.minute_buckets = defaultdict(dict)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None

        self.blocked_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._handle_held_option(slice)

        spy_bar = None
        if slice.Bars is not None and self.spy_symbol in slice.Bars:
            spy_bar = slice.Bars[self.spy_symbol]

        if spy_bar is None:
            return

        completed_bar = self._build_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        bar_end = completed_bar["end"]
        close = completed_bar["close"]

        old_fast = None
        old_slow = None

        if len(self.closes) >= self.slow_period:
            old_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            old_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (dtime(9, 45) <= bar_end.time() <= dtime(14, 30)):
            return

        self._try_enter(slice, bar_end.date())

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if self.entry_price is None and order_event.FillQuantity > 0:
                    self.entry_price = order_event.FillPrice
                    self.held_symbol = order_event.Symbol
                    self.held_expiry = self._get_expiry(order_event.Symbol)

                    self.Debug(
                        "ENTRY filled: {} @ {:.4f}".format(
                            order_event.Symbol.Value,
                            order_event.FillPrice
                        )
                    )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "EXIT filled: {} @ {:.4f}".format(
                        order_event.Symbol.Value,
                        order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.held_expiry = None
                self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.spy_liquidation_ticket is not None
            and order_event.OrderId == self.spy_liquidation_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.spy_liquidation_ticket = None

    def _build_five_minute_bar(self, minute_bar):
        end = minute_bar.EndTime

        if end.time() < dtime(9, 31) or end.time() > dtime(16, 0):
            return None

        bucket_minute = ((end.minute - 1) // 5) * 5
        bucket_start = datetime(
            end.year,
            end.month,
            end.day,
            end.hour,
            bucket_minute
        )

        if bucket_start.time() < dtime(9, 30):
            return None

        key = (bucket_start.date(), bucket_start.time())
        bucket = self.minute_buckets[key]
        bucket[end] = minute_bar

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if not all(timestamp in bucket for timestamp in expected_times):
            if end >= expected_times[-1]:
                self.minute_buckets.pop(key, None)
            return None

        bars = [bucket[timestamp] for timestamp in expected_times]
        self.minute_buckets.pop(key, None)

        return {
            "end": expected_times[-1],
            "close": bars[-1].Close
        }

    def _try_enter(self, slice: Slice, algorithm_date):
        if self.blocked_date == algorithm_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            return

        chains = []
        if slice.OptionChains is not None:
            chains = list(slice.OptionChains.Values)

        if len(chains) == 0:
            self.Debug("ENTRY skipped: no option chain")
            return

        chain = None
        for candidate in chains:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("ENTRY skipped: SPY option chain unavailable")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if len(eligible_expiries) == 0:
            self.Debug("ENTRY skipped: no eligible expiration")
            return

        selected_expiry = eligible_expiries[0]

        underlying_price = self.spy.Price
        if underlying_price is None or underlying_price <= 0:
            self.Debug("ENTRY skipped: invalid SPY price")
            return

        candidates = [
            contract
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike > 0
        ]

        if len(candidates) == 0:
            self.Debug("ENTRY skipped: no eligible call contracts")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                abs(float(contract.Strike) - float(underlying_price)),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover"
        )

    def _handle_held_option(self, slice: Slice):
        if self.held_symbol is None:
            return

        current_date = self.Time.date()

        if self.held_expiry is not None:
            expiry_date = self.held_expiry.date()

            if current_date >= expiry_date:
                self.blocked_date = current_date
                self.Debug("EXPIRATION guard: liquidating {}".format(
                    self.held_symbol.Value
                ))
                self._submit_exit("Expiration guard")
                return

            preceding_trading_day = self._preceding_trading_day(expiry_date)

            if (
                current_date == preceding_trading_day
                and self.Time.time() >= dtime(15, 45)
            ):
