                    self.held_symbol.Value
                ))
                self._submit_exit("Expiration time stop")
                return

        if self.entry_price is None:
            return

        quote = None
        if slice.QuoteBars is not None and self.held_symbol in slice.QuoteBars:
            quote = slice.QuoteBars[self.held_symbol]

        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.Debug("PROFIT TARGET: liquidating {}".format(
                self.held_symbol.Value
            ))
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket.Cancel("Replacing exit: " + reason)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity == 0:
            return

        self.blocked_date = self.Time.date()

        if self.spy_liquidation_ticket is None:
            self.Debug(
                "UNEXPECTED exercise/assignment: liquidating SPY position"
            )
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

    def _get_expiry(self, symbol):
        security = self.Securities[symbol]
        return security.Symbol.ID.Date

    def _preceding_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
        ):
            candidate -= timedelta(days=1)

        return candidate
