from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self._consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._consolidator.DataConsolidated += self._on_five_minute_bar

        self._closes = []
        self._current_slice = None
        self._last_minute = None
        self._consolidator_valid = False

        self._held_option = None
        self._entry_ticket = None
        self._exit_ticket = None
        self._entry_price = None
        self._entry_fills = 0
        self._entry_value = 0
        self._no_entry_date = None
        self._expiration_processed_date = None

    def OnData(self, slice: Slice):
        self._current_slice = slice

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_consolidator(spy_bar)

        self._handle_unexpected_spy_position()

        if self._held_option is None:
            return

        held = self._held_option
        expiry_date = held.ID.Date.date()
        current_date = self.Time.date()

        # Never intentionally hold through expiration.
        if current_date >= expiry_date:
            if self._expiration_processed_date != current_date:
                self._expiration_processed_date = current_date
                self._no_entry_date = current_date
                self._submit_exit("expiration")
            return

        # Time stop at 15:45 on the immediately preceding trading day.
        if self.Time.hour == 15 and self.Time.minute == 45:
            previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
                DateTime(expiry_date.year, expiry_date.month, expiry_date.day)
            ).date()

            if current_date == previous_trading_day:
                self._submit_exit("time stop")
                return

        # Profit target uses only a strictly positive current bid/ask midpoint.
        quote = slice.QuoteBars.get(held.Symbol)
        if quote is None:
            return

        bid = quote.Bid
        ask = quote.Ask

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self._entry_price is not None and midpoint >= 1.5 * self._entry_price:
            self._cancel_open_exit_order()
            self._submit_exit("profit target")

    def _update_consolidator(self, bar: TradeBar):
        current_time = self.Time
        current_date = current_time.date()

        if current_time.hour < 9 or (
            current_time.hour == 9 and current_time.minute < 30
        ) or current_time.hour >= 16:
            return

        if self._last_minute is None or self._last_minute.date() != current_date:
            self._consolidator = TradeBarConsolidator(timedelta(minutes=5))
            self._consolidator.DataConsolidated += self._on_five_minute_bar
            self._consolidator_valid = current_time.minute % 5 == 0
            self._last_minute = current_time
        else:
            gap = current_time - self._last_minute
            if gap != timedelta(minutes=1):
                self._consolidator_valid = False

            self._last_minute = current_time

            # Resume only at a true New York clock boundary.
            if not self._consolidator_valid:
                if current_time.minute % 5 == 0:
                    self._consolidator = TradeBarConsolidator(
                        timedelta(minutes=5)
                    )
                    self._consolidator.DataConsolidated += (
                        self._on_five_minute_bar
                    )
                    self._consolidator_valid = True
                else:
                    return

        if self._consolidator_valid:
            self._consolidator.Update(bar)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        close = float(bar.Close)

        previous_fast = None
        previous_slow = None

        if len(self._closes) >= 20:
            previous_fast = sum(self._closes[-5:]) / 5.0
            previous_slow = sum(self._closes[-20:]) / 20.0

        self._closes.append(close)

        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        current_fast = sum(self._closes[-5:]) / 5.0
        current_slow = sum(self._closes[-20:]) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or
             (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or
             (end_time.hour == 14 and end_time.minute <= 30))
        )

        if bullish_crossover and eligible_time:
            self._try_enter_call()

    def _try_enter_call(self):
        current_date = self.Time.date()

        if self._no_entry_date == current_date:
            return

        if self._held_option is not None:
            return

        if self._is_order_open(self._entry_ticket):
            return

        if self._current_slice is None:
            return

        chain = None
        for candidate in self._current_slice.OptionChains.Values:
            if candidate.Symbol == self.spy_option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain in Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        underlying_price = float(self.Securities[self.spy].Price)

        contracts = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not contracts:
            self.Debug(
                "Skipped call selection: no call contract at selected expiration."
            )
            return

        selected = min(
            contracts,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                contract.Symbol.Value
            )
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_fills = 0
        self._entry_value = 0
        self._entry_price = None

        self.Debug(
            f"Call entry submitted: {selected.Symbol.Value}, "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                fill_quantity = abs(order_event.FillQuantity)

                if fill_quantity > 0:
                    self._entry_fills += fill_quantity
                    self._entry_value += (
                        fill_quantity * float(order_event.FillPrice)
                    )
                    self._entry_price = (
                        self._entry_value / self._entry_fills
                    )

                    self._held_option = self._entry_ticket.Symbol

                    self.Debug(
                        f"Call entry filled: {self._held_option.Value}, "
                        f"price={self._entry_price:.4f}"
                    )

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    f"Call exit filled: {self._exit_ticket.Symbol.Value}, "
                    f"price={order_event.FillPrice:.4f}"
                )

                self._held_option = None
                self._exit_ticket = None
                self._entry_price = None
                self._entry_fills = 0
                self._entry_value = 0

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        ):
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self.Debug("Call entry order did not remain open.")
                self._entry_ticket = None

            if (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self._exit_ticket = None

        self._handle_unexpected_spy_position()

    def _submit_exit(self, reason):
        if self._held_option is None:
            return

        if self._is_order_open(self._exit_ticket):
            return

        quantity = self.Portfolio[self._held_option].Quantity

        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(
            self._held_option,
            -quantity
        )

        self.Debug(
            f"Call exit submitted: reason={reason}, "
            f"quantity={quantity}"
        )

    def _cancel_open_exit_order(self):
        if self._is_order_open(self._exit_ticket):
            self._exit_ticket.Cancel("Canceled before replacement exit order.")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity != 0:
            self._no_entry_date = self.Time.date()

            self.Debug(
                f"Unexpected SPY equity position detected "
                f"(quantity={spy_quantity}); liquidating immediately."
            )

            self.MarketOrder(self.spy, -spy_quantity)

    @staticmethod
    def _is_order_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
