                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self.held_option.Value,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled or
                order_event.Status == OrderStatus.Canceled or
                order_event.Status == OrderStatus.Invalid
            ):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Call exit filled: {0} at {1}".format(
                            order_event.Symbol.Value,
                            order_event.FillPrice
                        )
                    )
                    self.held_option = None
                    self.entry_price = None
                    self.no_entry_date = self.Time.date()

                self.exit_ticket = None

        order_type = getattr(order_event, "OrderType", None)

        if (
            order_type == OrderType.OptionExercise or
            "exercise" in str(getattr(order_event, "Message", "")).lower() or
            "assign" in str(getattr(order_event, "Message", "")).lower()
        ):
            self.Debug(
                "Unexpected option exercise or assignment: {0}".format(
                    order_event.Message
                )
            )
            self.HandleUnexpectedEquityPosition()

    def HandleUnexpectedEquityPosition(self):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating {0} shares."
                .format(quantity)
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.no_entry_date = self.Time.date()

    def GetCurrentOptionChain(self, slice):
        option_chains = getattr(slice, "OptionChains", None)

        if option_chains is None:
            return None

        return option_chains.get(self.option_symbol)

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def IsOrderOpen(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
