        self.ProcessProfitTarget(slice)

    def ProcessMinuteBar(self, minute_bar: TradeBar, slice: Slice):
        local_start = minute_bar.Time
        if local_start.tzinfo is not None:
            local_start = local_start.replace(tzinfo=None)

        session_start = time(9, 30)
        session_end = time(16, 0)

        if local_start.time() < session_start or local_start.time() >= session_end:
            return

        bucket_minute = (local_start.minute // 5) * 5
        bucket_start = local_start.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = []

        # Duplicate minute data must not count twice.
        if any(bar.Time == minute_bar.Time for bar in self.bucket_bars):
            return

        self.bucket_bars.append(minute_bar)

        # A valid five-minute bar requires all five minute bars.
        if local_start.minute % 5 != 4:
            return

        bars = sorted(self.bucket_bars, key=lambda bar: bar.Time)

        if len(bars) != 5:
            self.bucket_bars = []
            return

        for first, second in zip(bars, bars[1:]):
            if second.Time - first.Time != timedelta(minutes=1):
                self.bucket_bars = []
