        if len(self.closes) < self.slow_period:
            self.bucket_bars = []
            return

        previous_values = self.closes[:-1]
        previous_fast = sum(previous_values[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous_values[-self.slow_period:]) / self.slow_period

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        if (
            eligible_start <= bar_end.time() <= eligible_end
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.TryEnter(slice, consolidated_close, bar_end.date())

        self.bucket_bars = []

