        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_option:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def TimeStop(self):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        today = self.Time.date()

        if self.IsImmediatelyBeforeExpirationTradingDay(today, expiry):
            self.SubmitExit("expiration time stop")

    def ProcessExpiration(self):
        if self.expiration_processed_today:
            return

        self.expiration_processed_today = True

        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()

        if self.Time.date() >= expiry:
            self.no_entry_today = True
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        quantity = int(self.Portfolio[self.held_option].Quantity)
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
