            tag=reason
        )
        self.Debug(
            "Exit submitted: {} | {} | quantity={}".format(
                self.held_option.Value,
                reason,
                quantity
            )
        )

    def HandleUnexpectedSpyPosition(self):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity != 0:
            self.no_entry_today = True
