class SpyBullishCallCrossover(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        equity = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy = equity.symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        self.option = option.symbol

        # Broad universe: weekly and standard expirations, wide strike range.
        option.set_filter(
            lambda universe: universe
                .include_weeklys()
                .strikes(-100, 100)
                .expiration(7, 365)
        )

        # Manually updated only from five-minute bars in this backtest period.
        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_end = None
        self._bucket_close = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def on_data(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_option_expiration()
        self._process_option_exit(slice)
        self._process_spy_minute_bar(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        bar = slice.bars.get(self.spy)
        if bar is None:
            return

        bar_end = bar.end_time
        bar_start = bar_end - timedelta(minutes=1)

        # Only regular NYSE session data.
        if bar_start.time() < time(9, 30) or bar_start.time() >= time(16, 0):
            return

        minutes_from_open = int((bar_start - bar_start.replace(
            hour=9, minute=30, second=0, microsecond=0
        )).total_seconds() // 60)

        bucket_start = bar_start.replace(
            hour=9, minute=30, second=0, microsecond=0
        ) + timedelta(minutes=(minutes_from_open // 5) * 5)
        bucket_end = bucket_start + timedelta(minutes=5)

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._complete_five_minute_bar()

        if self._bucket_start is None or bucket_start != self._bucket_start:
            self._bucket_start = bucket_start
            self._bucket_end = bucket_end

        self._bucket_close = bar.close

        # A bar is completed only when actual minute data reaches its boundary.
        if bar_end >= self._bucket_end:
            self._complete_five_minute_bar()

    def _complete_five_minute_bar(self):
        if self._bucket_start is None or self._bucket_close is None:
            return

        completed_end = self._bucket_end
        close = self._bucket_close

        previous_ready = self.fast.is_ready and self.slow.is_ready
        previous_fast = self.fast.current.value if previous_ready else None
        previous_slow = self.slow.current.value if previous_ready else None

        self.fast.update(completed_end, close)
        self.slow.update(completed_end, close)

        if previous_ready and self.fast.is_ready and self.slow.is_ready:
            bullish_cross = (
                previous_fast <= previous_slow
                and self.fast.current.value > self.slow.current.value
            )

            eligible_time = time(9, 45) <= completed_end.time() <= time(14, 30)

            if bullish_cross and eligible_time:
                self._evaluate_entry()

        self._bucket_start = None
        self._bucket_end = None
        self._bucket_close = None

    def _evaluate_entry(self):
        today = self.time.date()

