        self.expiration_date = None
        self.time_stop_date = None

        self.no_reentry_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)
        self._process_expiration(current_date)

        if self.held_option is not None:
            self._evaluate_option_exit(slice, current_date)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime.replace(second=0, microsecond=0)
        current_date = end.date()

        # Regular-session SPY minute bars are expected to end from 09:31 through 16:00.
        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        anchor = datetime.combine(current_date, time(9, 30))
        minutes_from_anchor = int((end - anchor).total_seconds() // 60)

        if minutes_from_anchor < 1:
            return

        bucket_number = (minutes_from_anchor - 1) // 5
        bucket_end = anchor + timedelta(minutes=(bucket_number + 1) * 5)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_minute_bars = {}

        self.current_minute_bars[end] = bar

        if end != bucket_end:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        # Missing minute data means the five-minute bar is discarded.
        if not all(t in self.current_minute_bars for t in expected_times):
            self.current_minute_bars = {}
            return

        five_minute_close = self.current_minute_bars[bucket_end].Close
        self.current_minute_bars = {}

        self.closes.append(float(five_minute_close))

        if len(self.closes) < self.slow_period:
            return

        fast_now = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow_now = sum(self.closes) / self.slow_period

        previous_fast = getattr(self, "previous_fast", None)
        previous_slow = getattr(self, "previous_slow", None)

        self.previous_fast = fast_now
        self.previous_slow = slow_now

        if previous_fast is None or previous_slow is None:
            return

        crossover = (
            previous_fast <= previous_slow
            and fast_now > slow_now
        )

        if not crossover:
            return

        if not (
            time(9, 45) <= bucket_end.time() <= time(14, 30)
        ):
            return

        self._try_enter(slice, bucket_end.date())

    def _try_enter(self, slice: Slice, signal_date: date):
        if self.no_reentry_date == signal_date:
            return

        if self.held_option is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        selected_expiration = expirations[0]

        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.CALL
        ]

        if not calls:
            self.Debug(
                f"{self.Time}: skipped entry; no call at "
                f"{selected_expiration}"
            )
            return

        underlying_price = float(self.Securities[self.spy].Price)
        if underlying_price <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price")
            return

        # Strike rule: choose the call with the nearest strike to SPY.
        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        if self.entry_ticket is None:
            self.Debug(f"{self.Time}: skipped entry; order was not submitted")
            return

        self.Debug(
            f"{self.Time}: entry submitted, {selected.Symbol}, "
            f"expiry={selected_expiration}, strike={selected.Strike}"
        )

    def _evaluate_option_exit(self, slice: Slice, current_date: date):
        if self.held_option is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        # Time stop applies at or after 15:45 on the immediately preceding
        # trading day, even if no option quote is available.
        if (
            self.time_stop_date == current_date
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        contract_data = slice.OptionChains.get(self.option.Symbol)
        quote = None

        if contract_data is not None:
            for contract in contract_data:
                if contract.Symbol == self.held_option:
                    quote = contract
                    break

        if quote is None:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * float(self.entry_price)
        ):
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_option]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        self._cancel_open_exit_orders()

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        if self.exit_ticket is not None:
            self.Debug(
                f"{self.Time}: exit submitted, {self.held_option}, "
                f"reason={reason}"
            )

    def _process_expiration(self, current_date: date):
        if self.held_option is None:
            return

        if (
            self.expiration_date is not None
            and current_date >= self.expiration_date
        ):
            self.no_reentry_date = current_date

            if not self._ticket_is_open(self.exit_ticket):
                self._submit_exit("expiration safeguard")

    def _handle_unexpected_spy_position(self, current_date: date):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity == 0:
            return

        self.no_reentry_date = current_date

        if not self._ticket_is_open(self.spy_liquidation_ticket):
            self.Debug(
                f"{self.Time}: unexpected SPY equity position detected; "
                f"liquidating quantity {quantity}"
            )
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = (
                    order_event.Symbol.ID.Date.date()
                )
                self.time_stop_date = self._previous_trading_day(
                    self.expiration_date
                )

                self.Debug(
                    f"{self.Time}: entry filled, {self.held_option}, "
                    f"price={self.entry_price}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"{self.Time}: exit filled, {order_event.Symbol}, "
                    f"price={order_event.FillPrice}"
                )

                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
                self.time_stop_date = None
                self.exit_ticket = None

        message = str(order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.no_reentry_date = self.Time.date()
            self.Debug(
                f"{self.Time}: unexpected exercise/assignment event: "
                f"{order_event.Message}"
            )

    def _previous_trading_day(self, expiry_date: date) -> date:
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.spy_security.Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _cancel_open_exit_orders(self):
        if self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

    @staticmethod
    def _ticket_is_open(ticket) -> bool:
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )
