        bar_end = minute_bar.EndTime
        bar_date = bar_end.date()

        if self.current_bar_date != bar_date:
            self.minute_bars.clear()
            self.current_bar_date = bar_date

        end_time = bar_end.time()
        if not (time(9, 31) <= end_time <= time(16, 0)):
            return False

        minute_key = (bar_date, end_time.hour, end_time.minute)
        self.minute_bars[minute_key] = minute_bar

        # A five-minute bar closes at 09:35, 09:40, ..., 16:00.
        if end_time.minute % 5 != 0:
            return False

        expected_keys = []
        end_minutes = end_time.hour * 60 + end_time.minute

        for minute_number in range(end_minutes - 4, end_minutes + 1):
