            minute = minute_number % 60
            expected_keys.append((bar_date, hour, minute))

        if not all(key in self.minute_bars for key in expected_keys):
            for key in list(self.minute_bars):
                if key[0] == bar_date and key[2] <= end_time.minute:
                    del self.minute_bars[key]
            return False

        closes = [self.minute_bars[key].Close for key in expected_keys]

        for key in expected_keys:
            self.minute_bars.pop(key, None)

        self.previous_fast = (
            sum(self.fast_values) / len(self.fast_values)
            if len(self.fast_values) == self.fast_period
            else None
        )
        self.previous_slow = (
            sum(self.slow_values) / len(self.slow_values)
            if len(self.slow_values) == self.slow_period
            else None
        )

        close = closes[-1]
        self.fast_values.append(close)
        self.slow_values.append(close)

        current_fast = (
            sum(self.fast_values) / self.fast_period
            if len(self.fast_values) == self.fast_period
            else None
        )
        current_slow = (
            sum(self.slow_values) / self.slow_period
            if len(self.slow_values) == self.slow_period
            else None
        )

        if (
            self.previous_fast is None
            or self.previous_slow is None
            or current_fast is None
            or current_slow is None
        ):
            return False

        return (
            self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

