        midpoint = None

        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close

            if bid is not None and ask is not None and bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0

        profit_target = (
            midpoint is not None
            and midpoint >= 1.50 * float(self.entry_price)
        )

        if profit_target:
            self._submit_exit("50% profit target reached.")
        elif time_stop:
            self._submit_exit("Expiration time stop reached.")

