        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity
        )
        self.Debug("Exit submitted: {}".format(reason))

    def _handle_expiration_processing(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self._submit_exit("Unexpected position at expiration processing.")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity == 0:
            self.equity_cleanup_ticket = None
            return

        if self.equity_cleanup_ticket is not None and self.equity_cleanup_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
        self.equity_cleanup_ticket = self.MarketOrder(
            self.spy,
            -spy_quantity
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = self.entry_ticket.Symbol
                    self.entry_price = self.entry_ticket.AverageFillPrice

                    if self.entry_price <= 0:
                        self.entry_price = order_event.FillPrice

                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self.held_option.Value,
                            float(self.entry_price)
                        )
                    )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Option exit filled.")
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.entry_ticket = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected exercise or assignment event received.")
            spy_quantity = self.Portfolio[self.spy].Quantity
            if spy_quantity != 0:
                self.equity_cleanup_ticket = self.MarketOrder(
