from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.held_option = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None

        self.five_minute_bucket = None
        self.bucket_bars = {}

        self.expiration_block_date = None
        self.equity_cleanup_ticket = None
        self.equity_cleanup_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        # Immediately remove unexpected SPY equity positions, such as assignment.
        equity_quantity = self.Portfolio[self.spy_symbol].Quantity
        if equity_quantity != 0:
            if self.equity_cleanup_date != today:
                self.Debug(
                    f"Unexpected exercise or assignment handling: "
                    f"liquidating {equity_quantity} SPY shares."
                )
                if self.equity_cleanup_ticket is None or not self._order_open(
                    self.equity_cleanup_ticket
                ):
                    self.equity_cleanup_ticket = self.MarketOrder(
                        self.spy_symbol, -equity_quantity
                    )
                self.equity_cleanup_date = today
            return

        # Never intentionally hold an option into its expiration date.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.expiration_block_date = today
                self._submit_exit("expiration processing")
            else:
                previous_trading_day = (
                    self.Securities[self.spy_symbol]
                    .Exchange
                    .Hours
                    .GetPreviousTradingDay(self.held_option.ID.Date)
                    .date()
                )

                if (
                    today == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._submit_exit("pre-expiration time stop")
                else:
                    self._check_profit_target(slice)

        # Feed the actual minute bar into the clock-aligned five-minute builder.
        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._update_five_minute_bar(bar)

    def _update_five_minute_bar(self, bar: TradeBar):
        local_time = bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        # Regular-session bars only.
        if local_time.time() < datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time.time() >= datetime.strptime("16:00", "%H:%M").time():
            return

        minute = (local_time.minute // 5) * 5
        bucket_start = local_time.replace(
            minute=minute, second=0, microsecond=0
        )

        if self.five_minute_bucket is None:
            self.five_minute_bucket = bucket_start

        if bucket_start != self.five_minute_bucket:
            self._finalize_five_minute_bar(self.five_minute_bucket)
            self.bucket_bars = {}
            self.five_minute_bucket = bucket_start

        # Store only actual minute bars. Missing minutes are not synthesized.
        self.bucket_bars[local_time] = bar

    def _finalize_five_minute_bar(self, bucket_start):
        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        # A missing minute means the consolidated five-minute bar is missing.
        if not all(t in self.bucket_bars for t in expected_times):
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close
        bar_end = bucket_start + timedelta(minutes=5)

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(bar_end, close))
        self.slow.Update(IndicatorDataPoint(bar_end, close))

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        end_time = bar_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if (
            bullish_cross
            and eligible_start <= end_time <= eligible_end
            and self.expiration_block_date != self.Time.date()
            and self.held_option is None
            and not self._entry_order_open()
        ):
            self._try_enter()

    def _try_enter(self):
        if self.current_slice is None:
            self.Debug("Skipped entry: current Slice unavailable.")
            return

        underlying_price = self.Securities[self.spy_symbol].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(self.current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call expiration or strike.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        same_expiry = [
            contract
            for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        # Select the closest available call strike to the current raw SPY price.
        selected = min(
            same_expiry,
            key=lambda contract: (
