        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.TimeStop
        )

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into its expiration date.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.blocked_entry_date = today
                self.SubmitExit("Expiration liquidation")

        # Immediately remove unexpected assigned/exercised SPY equity.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.blocked_entry_date = today
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(self.spy, -spy_quantity, "Unexpected exercise/assignment")

        # Evaluate the profit target on every minute Slice.
        self.EvaluateProfitTarget(slice)

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self.ProcessMinuteBar(spy_bar, slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time

        # Only regular-session minute bars are used.
        if local_time.time() < time(9, 31) or local_time.time() > time(16, 0):
            return

        session_start_minutes = 9 * 60 + 31
        minute_number = local_time.hour * 60 + local_time.minute
        offset = minute_number - session_start_minutes

        if offset < 0:
            return

        bucket_index = offset // 5
        bucket_end = local_time.replace(
            hour=9,
            minute=36,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_index * 5)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end

        if bucket_end != self.current_bucket_end:
            self.EmitFiveMinuteBar(slice)

            self.current_bucket_bars = {}
            self.current_bucket_end = bucket_end

        self.current_bucket_bars[local_time] = bar

        # Emit as soon as the fifth minute bar arrives.
        if len(self.current_bucket_bars) == 5:
            self.EmitFiveMinuteBar(slice)
            self.current_bucket_bars = {}
            self.current_bucket_end = None

    def EmitFiveMinuteBar(self, slice: Slice):
        if self.current_bucket_end is None:
            return

        bars = list(self.current_bucket_bars.values())
        if len(bars) != 5:
            # Missing minute data: discard the incomplete interval.
            return

        times = sorted(self.current_bucket_bars.keys())
        for i in range(1, len(times)):
            if times[i] - times[i - 1] != timedelta(minutes=1):
                return

        close = bars[-1].Close

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        bar_end_time = self.current_bucket_end.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_cross and eligible_time:
            self.TryEnter(slice)

    def TryEnter(self, slice: Slice):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_option is not None:
            return

        if self.IsOrderOpen(self.entry_ticket):
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]

        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call contract at selected expiration.")
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: no current SPY price in Slice.")
            return

        underlying_price = slice.Bars[self.spy].Close

        # Select the nearest-to-ATM call at the selected expiration.
        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute SMA crossover"
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            return

        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def TimeStop(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = self.PreviousTradingDay(expiry_date)

        if self.Time.date() == previous_trading_day:
            self.SubmitExit("Expiration-eve time stop")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            reason
        )

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def IsOrderOpen(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entered {self.held_option} at {self.entry_price:.2f}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exited {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}"
                )
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.NoneStatus
        ):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.Debug("Entry order was not filled.")
                self.entry_ticket = None

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_ticket = None
