        # Regular session only.
        if minute_of_day < 570 or minute_of_day >= 960:
            return

        bucket_minute = 570 + ((minute_of_day - 570) // 5) * 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self._bucket is not None and self._bucket["start"] != bucket_start:
            self._finish_bucket(slice)

        if self._bucket is None:
            self._bucket = {
                "start": bucket_start,
                "count": 0,
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": minute_bar.Volume,
                "minutes": set()
            }

        # Ignore duplicate minute data.
        minute_key = bar_time.replace(second=0, microsecond=0)
        if minute_key in self._bucket["minutes"]:
            return

        self._bucket["minutes"].add(minute_key)
        self._bucket["count"] += 1
        self._bucket["high"] = max(self._bucket["high"], minute_bar.High)
        self._bucket["low"] = min(self._bucket["low"], minute_bar.Low)
        self._bucket["close"] = minute_bar.Close
        self._bucket["volume"] += minute_bar.Volume

    def _finish_bucket(self, slice: Slice):
        bucket = self._bucket
        self._bucket = None

