        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * float(self._entry_price):
            self._submit_option_exit("50% profit target")

    def _get_current_option_quote(self, slice: Slice, symbol):
        quote_bar = slice.QuoteBars.get(symbol)
        if quote_bar is not None and quote_bar.Bid is not None and quote_bar.Ask is not None:
            bid = quote_bar.Bid.Close
            ask = quote_bar.Ask.Close
            if bid is not None and ask is not None:
                return float(bid), float(ask)

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        return None

    def _submit_option_exit(self, reason):
        if self._held_option is None:
            return

        if self._exit_ticket is not None and self._order_is_open(self._exit_ticket):
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity == 0:
            return

        if self._exit_ticket is not None and self._order_is_open(self._exit_ticket):
            self.Transactions.CancelOrder(self._exit_ticket.OrderId)

        self._exit_ticket = self.MarketOrder(
