            -quantity,
            tag=reason
        )
        self.Debug(
            f"Exit submitted: {self._held_option.Value}, "
            f"quantity={quantity}, reason={reason}"
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self._equity_liquidation_ticket is not None
            and self._order_is_open(self._equity_liquidation_ticket)
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected, liquidating quantity={quantity}."
        )
        self._equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self._held_option = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self._held_option.Value}, "
                    f"price={self._entry_price}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.Debug(f"Entry order ended: {order_event.Status}")
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol.Value}")
                self._held_option = None
                self._entry_price = None
                self._exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._exit_ticket = None

    def _previous_trading_day(self, date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )
