from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_start = None
        self.bucket_bars = []
        self.bucket_valid = True
        self.previous_fast = None
        self.previous_slow = None
        self.latest_spy_price = None

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.blocked_entry_date = None
        self.assignment_ticket = None

    def OnData(self, slice: Slice):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0 and self.assignment_ticket is None:
            self.Debug("Unexpected SPY exercise/assignment; liquidating equity")
            self.assignment_ticket = self.MarketOrder(self.spy, -spy_quantity)

        if self.held_symbol is not None:
            current_date = self.Time.date()

            if self.expiration_date is not None and current_date >= self.expiration_date:
                self.blocked_entry_date = current_date
                self.SubmitExit("expiration")
            else:
                self.CheckProfitTarget(slice)

                if (
                    self.time_stop_date == current_date
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self.SubmitExit("time stop")

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self.latest_spy_price = float(minute_bar.Close)
        self.ConsumeMinuteBar(minute_bar, slice)

    def ConsumeMinuteBar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime

        if (end.hour, end.minute) < (9, 31):
            return

        if (end.hour, end.minute) > (16, 0):
            return

        bar_start = end - timedelta(minutes=1)
        bucket_start = bar_start.replace(
            minute=(bar_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        elif bucket_start != self.bucket_start:
            self.FinishBucket(slice)
            self.bucket_start = bucket_start
            self.bucket_bars = []
            self.bucket_valid = True

        expected_end = (
            self.bucket_start + timedelta(minutes=1)
            if not self.bucket_bars
            else self.bucket_bars[-1].EndTime + timedelta(minutes=1)
        )

        if end != expected_end:
            self.bucket_valid = False

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self.FinishBucket(slice)

    def FinishBucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        if not self.bucket_valid or len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        close = float(self.bucket_bars[-1].Close)

        self.previous_fast = (
            float(self.fast.Current.Value)
            if self.fast.IsReady else None
        )
        self.previous_slow = (
            float(self.slow.Current.Value)
            if self.slow.IsReady else None
        )

        bar_end = self.bucket_start + timedelta(minutes=5)
        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        eligible_time = (
            (bar_end.hour, bar_end.minute) >= (9, 45)
            and (bar_end.hour, bar_end.minute) <= (14, 30)
        )

        if crossover and eligible_time:
            self.TryEntry(slice)

        self.bucket_bars = []

    def TryEntry(self, slice: Slice):
        today = self.Time.date()

        if self.held_symbol is not None:
            return

        if self.IsOpen(self.entry_ticket):
            return

        if self.blocked_entry_date == today:
            return

        minimum_expiration = today + timedelta(days=7)
        selected_expiration = None
        selected_chain = None

        for chain in slice.OptionChains.Values:
            expirations = [
                contract.Expiry.date()
                for contract in chain.Contracts.Values
                if contract.Expiry.date() >= minimum_expiration
            ]

            if not expirations:
                continue

            expiration = min(expirations)

            if (
                selected_expiration is None
                or expiration < selected_expiration
            ):
                selected_expiration = expiration
                selected_chain = chain

        if selected_chain is None:
            self.Debug(
                "Skipped entry: no eligible expiration in current Slice"
            )
            return

        calls = [
            contract
            for contract in selected_chain.Contracts.Values
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
            )
        ]

        if not calls:
            self.Debug(
                "Skipped entry: no call contracts at selected expiration"
            )
            return

        if self.latest_spy_price is None:
            self.Debug("Skipped entry: no current SPY price")
            return

        contract = min(
            calls,
            key=lambda c: (
                abs(float(c.Strike) - self.latest_spy_price),
                float(c.Strike),
                str(c.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Entry submitted: " + str(contract.Symbol))

    def CheckProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.IsOpen(self.exit_ticket):
            return

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_symbol)

            if contract is None:
                continue

            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)

            if bid <= 0 or ask <= 0:
                return

            midpoint = (bid + ask) / 2.0

            if midpoint >= 1.5 * self.entry_price:
                self.SubmitExit("profit target")

            return

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.IsOpen(self.exit_ticket):
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity
        )
        self.Debug(
            "Exit submitted (" + reason + "): " + str(self.held_symbol)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            order_event.Symbol == self.spy
            and self.Portfolio[self.spy].Quantity != 0
            and self.assignment_ticket is None
        ):
            self.Debug("Unexpected SPY exercise/assignment; liquidating equity")
            self.assignment_ticket = self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity
            )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = (
                    order_event.Symbol.ID.Date.date()
                )
                self.time_stop_date = self.PreviousTradingDay(
                    self.expiration_date
                )

                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.Debug("Entry skipped: order was not filled")

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(self.held_symbol))

            self.held_symbol = None
            self.entry_price = None
            self.expiration_date = None
            self.time_stop_date = None
            self.exit_ticket = None

    def PreviousTradingDay(self, expiration_date):
        day = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(day):
            day -= timedelta(days=1)

        return day

    @staticmethod
    def IsOpen(ticket):
        return (
            ticket is not None
            and ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

