        if self.held_symbol is None or self.expiry is None:
            return

        today = self.Time.date()

        if today >= self.expiry and self.expiration_processed != today:
            self.expiration_processed = today
            self.no_entry_today = True
            self.SubmitExit("Expiration liquidation")

