        if (
            self.time_stop_day == today
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self.SubmitExit("Pre-expiration time stop")
            return

        if self.exit_ticket is not None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        if self.EntryOrderOpen():
            self.entry_ticket.Cancel("Exit required")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted for {0}: {1}".format(
                self.held_symbol.Value,
                reason
            )
        )

    def GetPriorTradingDay(self, date):
        date -= timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(date):
            date -= timedelta(days=1)

        return date

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.expiry = self.held_symbol.ID.Date.date()
                self.time_stop_day = self.GetPriorTradingDay(self.expiry)

                self.Debug(
                    "Entered {0} at {1:F4}".format(
                        self.held_symbol.Value,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(
                    "Entry order did not fill: {0}".format(
                        order_event.Status
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(
                    "Exit {0}: {1}".format(
                        order_event.Status,
                        self.exit_ticket.Tag
                    )
                )

                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiry = None
                    self.time_stop_day = None

                self.exit_ticket = None

    def OnEndOfAlgorithm(self):
        self.SubscriptionManager.RemoveConsolidator(
            self.spy,
            self.consolidator
        )
