        if self.held_option is not None:
            self._evaluate_exit(data)

        # Consolidate the current SPY minute bar manually using New York
        # clock boundaries. A complete 09:30-09:35 bar is the first bar.
        if data.Bars.ContainsKey(self.spy):
            self._process_minute_bar(data.Bars[self.spy], data)

    def _process_minute_bar(self, bar, data):
        local_time = self.Time

        if local_time.weekday() >= 5:
            return

        session_start = time(9, 30)
        session_end = time(16, 0)

        if not (session_start <= local_time.time() < session_end):
            return

        bucket_minute = (local_time.minute // 5) * 5
        bucket_start = local_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._finish_bucket(data)
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        # Duplicate minute bars are ignored.
        self.bucket_bars[local_time] = bar

    def _finish_bucket(self, data):
        if self.bucket_start is None:
            return

        # Require all five actual minute bars. Missing intervals are not
        # synthesized or forward-filled.
        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected_times):
            self.bucket_bars = {}
            return

        close = self.bucket_bars[expected_times[-1]].Close
        bar_end = self.bucket_start + timedelta(minutes=5)

        self.closes.append(float(close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

