        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_bars = {}

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        if (
            bullish_cross
            and eligible_start <= bar_end.time() <= eligible_end
        ):
            self._evaluate_entry(data)

    def _evaluate_entry(self, data):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self._is_order_open(self.entry_ticket):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiration = current_date + timedelta(days=7)

        contracts = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
        ]

        if not contracts:
            self.Debug(
                "Skipped entry: no call expiration is at least seven calendar days away."
            )
            return

        selected_expiration = min(
            contract.Expiry.date() for contract in contracts
        )

        expiration_contracts = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiration
        ]

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: SPY price is unavailable.")
            return

        # Strike rule: select the nearest-at-the-money call.
        if not expiration_contracts:
            self.Debug("Skipped entry: no call contracts at selected expiration.")
            return

        selected = min(
            expiration_contracts,
            key=lambda contract: abs(contract.Strike - underlying_price)
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={selected_expiration} strike={selected.Strike}"
        )

    def _evaluate_exit(self, data):
        if self.held_option is None:
            return

        held = self.Portfolio[self.held_option]
        if held.Quantity <= 0:
            return

        # Time stop at 15:45 on the trading day immediately preceding expiry.
        expiration_date = self.held_option.ID.Date.date()
        if (
            self.Time.time() >= time(15, 45)
            and self._is_trading_day_immediately_before(
                self.Time.date(),
                expiration_date
            )
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self._is_order_open(self.exit_ticket):
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self._is_order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Canceled by replacement exit")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            quantity,
            tag=reason
        )

        self.Debug(
            f"Exit submitted: {self.held_option} reason={reason}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "SPY bullish crossover call entry":
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                self.held_option = order.Symbol
                self.entry_price = order_event.FillPrice

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Entry filled: {order.Symbol} price={order_event.FillPrice}"
                    )
                    self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(f"Entry order did not fill: {order_event.Status}")
                self.entry_ticket = None

        elif order.Tag in (
            "50 percent profit target",
            "Pre-expiration time stop",
            "Expiration liquidation",
            "Canceled by replacement exit"
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order.Symbol} price={order_event.FillPrice}"
                )

                if self.held_option == order.Symbol:
                    self.held_option = None
                    self.entry_price = None

                self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment detected.")

        if self.Portfolio[self.spy].Quantity != 0:
            quantity = -self.Portfolio[self.spy].Quantity
            self.MarketOrder(
                self.spy,
                quantity,
                tag="Unexpected exercise/assignment"
            )

        self.no_entry_date = self.Time.date()

    def _is_order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _is_trading_day_immediately_before(self, current_date, expiration_date):
        if current_date >= expiration_date:
            return False

        candidate = current_date + timedelta(days=1)

        while candidate < expiration_date:
            candidate += timedelta(days=1)

        if candidate != expiration_date:
            return False

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        return exchange_hours.IsDateOpen(
            datetime.combine(current_date, time.min)
        )

