        if self.spy in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_start = minute_bar.Time
        minute_of_day = local_start.hour * 60 + local_start.minute

        # Regular session: 09:30 through 16:00 New York time.
        if minute_of_day < 570 or minute_of_day >= 960:
            return

        bucket_index = (minute_of_day - 570) // 5
        expected_start_minute = 570 + bucket_index * 5
        bucket_key = (local_start.date(), bucket_index)

        if self._bucket_key != bucket_key:
            self._complete_bucket()
            self._bucket_key = bucket_key
            self._bucket_bars = []

        # Reject duplicate or out-of-order minute bars.
        if self._bucket_bars:
            previous = self._bucket_bars[-1].Time
            if (
                local_start.date() != previous.date()
                or (local_start - previous).total_seconds() != 60
            ):
                self._bucket_bars = []

        self._bucket_bars.append(minute_bar)

