                self._bucket_bars = []

                close = completed[-1].Close
                end_time = completed[-1].EndTime

                previous_fast = self.fast.Current.Value \
                    if self.fast.IsReady else None
                previous_slow = self.slow.Current.Value \
                    if self.slow.IsReady else None

                self.fast.Update(IndicatorDataPoint(self.spy, end_time, close))
                self.slow.Update(IndicatorDataPoint(self.spy, end_time, close))

                if (
                    previous_fast is not None
                    and previous_slow is not None
                    and self.fast.IsReady
                    and self.slow.IsReady
                ):
                    bullish_cross = (
                        previous_fast <= previous_slow
                        and self.fast.Current.Value > self.slow.Current.Value
                    )

                    end_local = end_time
                    eligible_time = (
                        end_local.hour > 9
                        or (end_local.hour == 9 and end_local.minute >= 45)
                    ) and (
                        end_local.hour < 14
                        or (end_local.hour == 14 and end_local.minute <= 30)
                    )

                    if bullish_cross and eligible_time:
                        self._try_enter(slice)

    def _complete_bucket(self):
        # Incomplete buckets are deliberately discarded.
        self._bucket_bars = []

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.no_entries_date == today:
            return

        if self.entry_order_id is not None:
            return

        if self.entry_symbol is not None:
            return

        chain = None
        if self.option_symbol in slice.OptionChains:
            chain = slice.OptionChains[self.option_symbol]

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)

        valid_contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
            and contract.Right == OptionRight.Call
        ]

        if not valid_contracts:
            self.Debug("Skipped call selection: no qualifying expiration/call.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in valid_contracts
        )

        same_expiry = [
            contract for contract in valid_contracts
            if contract.Expiry.date() == selected_expiry
        ]

        underlying_price = None
        if self.spy in slice.Bars:
            underlying_price = slice.Bars[self.spy].Close
        elif self.Securities[self.spy].Price > 0:
            underlying_price = self.Securities[self.spy].Price

        if underlying_price is None or underlying_price <= 0:
            self.Debug("Skipped call selection: unavailable SPY price.")
            return

        # Select the nearest-to-ATM call at the nearest valid expiration.
        selected = min(
            same_expiry,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        if selected is None:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(f"Submitted call entry: {selected.Symbol}")

    def _evaluate_profit_target(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        if self.entry_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.entry_symbol]

        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if self.entry_symbol is None:
            return

        if self.exit_order_id is not None:
            return

        self._cancel_open_exit_orders()

        quantity = self.Portfolio[self.entry_symbol].Quantity

        if quantity != 0:
            ticket = self.MarketOrder(
                self.entry_symbol,
                -quantity,
                tag=reason
            )
            if ticket is not None:
                self.exit_order_id = ticket.OrderId
                self.Debug(f"Submitted option exit: {reason}")

    def _cancel_open_exit_orders(self):
        for order_id in list(self.Transactions.GetOpenOrderTickets()):
            order = order_id.GetOrder()
            if order is not None and order.Symbol == self.entry_symbol:
                order_id.Cancel("Superseded by liquidation")

    def _previous_trading_day(self, target_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = target_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.entry_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None

                self.Debug(
                    f"Call entry filled: {self.entry_symbol}, "
                    f"price={self.entry_price:.4f}"
                )

            elif order_event.OrderId == self.exit_order_id:
                self.Debug(
                    f"Call exit filled: {order_event.Symbol}, "
                    f"price={order_event.FillPrice:.4f}"
                )
                self.exit_order_id = None
                self.entry_symbol = None
                self.entry_price = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if order_event.OrderId == self.entry_order_id:
                self.Debug("Call entry order canceled or invalid.")
                self.entry_order_id = None

            if order_event.OrderId == self.exit_order_id:
                self.Debug("Call exit order canceled or invalid.")
                self.exit_order_id = None
