from collections import deque
from datetime import datetime, timedelta

from QuantConnect import DataNormalizationMode, OptionRight, Resolution
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Orders import OrderStatus


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = {}
        self.bucket_data = None

        self.signal_bar_end = None
        self.last_processed_signal = None
        self.last_spy_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None

        self.current_date = None
        self.no_entry_today = False
        self.time_stop_date = None
        self.expiration_handled_date = None

    def OnData(self, slice):
        today = self.Time.date()

        if self.current_date != today:
            self.current_date = today
            self.no_entry_today = False
            self.time_stop_date = None
            self.expiration_handled_date = None

        # Immediately liquidate any SPY equity created by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"{self.Time}: unexpected exercise/assignment; "
                f"liquidating {spy_quantity} SPY shares"
            )
            self.MarketOrder(self.spy, -spy_quantity, tag="Unexpected exercise/assignment")
            self.no_entry_today = True

        # Expiration protection.
        if self.held_symbol is not None and self.expiration_date is not None:
            if today >= self.expiration_date:
                self.no_entry_today = True
                self._cancel_entry_order()
                self._submit_exit("Expiration protection")
                self.expiration_handled_date = today

        # Process the current SPY minute bar into a NY-clock-aligned five-minute bar.
        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar)

        # Apply the preceding-trading-day time stop.
        if (
            self.held_symbol is not None
            and self.expiration_date is not None
            and self.Time.hour == 15
            and self.Time.minute >= 45
            and today == self._previous_trading_day(self.expiration_date)
            and self.time_stop_date != today
        ):
            self.time_stop_date = today
            self._submit_exit("Expiration-eve time stop")

        # Evaluate the profit target on every minute Slice.
        self._evaluate_profit_target(slice)

        # Evaluate each newly completed eligible crossover exactly once.
        if (
            self.signal_bar_end is not None
            and self.signal_bar_end != self.last_processed_signal
        ):
            signal_time = self.signal_bar_end
            self.last_processed_signal = signal_time
            self.signal_bar_end = None

            if (
                signal_time.hour > 9
                or (signal_time.hour == 9 and signal_time.minute >= 45)
            ) and (
                signal_time.hour < 14
                or (signal_time.hour == 14 and signal_time.minute <= 30)
            ):
                self._evaluate_entry(slice)

    def _update_five_minute_bar(self, minute_bar):
        # TradeBar.Time is the minute's NY-clock start time. Buckets are
        # [09:30,09:35), [09:35,09:40), etc.; thus the first bar ends 09:35.
        t = minute_bar.Time
        if t.hour < 9 or (t.hour == 9 and t.minute < 30):
            return
        if t.hour > 16 or (t.hour == 16 and t.minute > 0):
            return

        bucket = t.replace(
            minute=(t.minute // 5) * 5,
            second=0,
            microsecond=0,
        )

        if self.bucket_start is None:
            self._start_bucket(bucket)
        elif bucket != self.bucket_start:
            self._finish_bucket()
            self._start_bucket(bucket)

        if t in self.bucket_bars:
            return

        expected_start = self.bucket_start
        expected_end = self.bucket_start + timedelta(minutes=5)

        if not (expected_start <= t < expected_end):
            return

        self.bucket_bars[t] = minute_bar

    def _start_bucket(self, bucket):
        self.bucket_start = bucket
        self.bucket_bars = {}

    def _finish_bucket(self):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data invalidates the five-minute bar. No synthetic
        # or forward-filled bar is produced.
        if not all(t in self.bucket_bars for t in expected_times):
            self.bucket_start = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close
        self.last_spy_price = close
        self._update_averages(close)

        bar_end = self.bucket_start + timedelta(minutes=5)

        if self.previous_fast is not None:
            fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            slow = sum(self.closes) / self.slow_period

            if (
                self.previous_fast <= self.previous_slow
                and fast > slow
            ):
                self.signal_bar_end = bar_end

        self.bucket_start = None
        self.bucket_bars = {}

    def _update_averages(self, close):
        if len(self.closes) >= self.fast_period:
            self.previous_fast = (
                sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            )

        if len(self.closes) >= self.slow_period:
            self.previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

    def _evaluate_entry(self, slice):
        if self.no_entry_today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            return

